/**
 * EXPERIMENTAL — the iframe-backed implementation of the {@link IEmbeddedCodeEditor}
 * seam (see `blockView.ts`). It embeds a third-party web editor (the *guest*,
 * e.g. `@vscode/sample-web-editor`) in an `<iframe>` and bridges it to the code
 * block using the `@vscode/web-editors` host↔guest protocol:
 *
 *   - document → editor : {@link IEmbeddedCodeEditor.setContent} → `host.setText`
 *   - editor → document : guest edit → `host.onDidChangeText` → {@link IEmbeddedCodeEditor.onEdit}
 *     as a whole-content {@link StringEdit}
 *   - sizing            : guest `reportSize` → `host.onDidReportSize` → logical and physical height
 *
 * Providers supply HTML and may provide a base URL for scripts and assets.
 * The host injects theme and sizing support, then loads it into pooled,
 * absolutely positioned frames. Logical placeholders remain in document flow.
 * Frames use `sandbox="allow-scripts"` (no `allow-same-origin`) → opaque
 * origin, matching the `WindowMessageTransport` posture.
 *
 * The implementation is exported by the markdown editor, while its web-editor
 * runtime is bundled into the package so consumers do not need a runtime
 * dependency on `@vscode/web-editors`.
 */

import { HubRpcConnection, JsonRpcChannel } from '@vscode/hubrpc';
import { WebEditorHost, WindowMessageTransport, type ContentType, type HostTransport, type PresentationMode, type PresentationPreferences } from '@vscode/web-editors';
import type { IDisposable } from '@vscode/observables';
import { OffsetRange } from '../core/offsetRange.js';
import { StringEdit } from '../core/stringEdit.js';
import type { IEmbeddedCodeEditor, IEmbeddedCodeEditorFactory } from './content/blockView.js';
import { clientDeltaToScrollDelta, getClippingClientRect, getElementClientRect } from './scrolling.js';

export type CodeBlockEditorSelector =
	| { readonly language: string }
	| { readonly languagePrefix: string };

export type IframeEmbeddedEditorProviderSelector = CodeBlockEditorSelector;

export interface CodeBlockEditorProviderDefinition {
	readonly id: string;
	readonly selector: CodeBlockEditorSelector;
}

export interface IframeEmbeddedEditorProvider extends CodeBlockEditorProviderDefinition {
	readonly resolve: (infoString: string) => Promise<ResolvedIframeEmbeddedEditor | undefined>;
	readonly createHostTransport?: (runtimeKey: string) => IframeEmbeddedEditorHostTransport;
}

export type IframeEmbeddedEditorHostTransport = HostTransport & IDisposable;

export type CodeBlockEditorProviderSelection<T> =
	| { readonly kind: 'match'; readonly provider: T }
	| { readonly kind: 'ambiguous'; readonly providers: readonly T[] };

export function selectCodeBlockEditorProvider<T extends CodeBlockEditorProviderDefinition>(
	providers: readonly T[],
	language: string,
): CodeBlockEditorProviderSelection<T> | undefined {
	const exact = providers.filter(provider => 'language' in provider.selector && provider.selector.language === language);
	if (exact.length > 0) {
		return exact.length === 1
			? { kind: 'match', provider: exact[0] }
			: { kind: 'ambiguous', providers: exact };
	}

	let bestLength = -1;
	let best: T[] = [];
	for (const provider of providers) {
		if (!('languagePrefix' in provider.selector) || !language.startsWith(provider.selector.languagePrefix)) {
			continue;
		}
		const length = provider.selector.languagePrefix.length;
		if (length > bestLength) {
			bestLength = length;
			best = [provider];
		} else if (length === bestLength) {
			best.push(provider);
		}
	}
	if (best.length === 0) {
		return undefined;
	}
	return best.length === 1
		? { kind: 'match', provider: best[0] }
		: { kind: 'ambiguous', providers: best };
}

export interface IframeSandboxOptions {
	readonly forms?: boolean;
	readonly downloads?: boolean;
	readonly pointerLock?: boolean;
	readonly clipboardWrite?: boolean;
}

export type ResolvedIframeEmbeddedEditorSandbox = IframeSandboxOptions;

/**
 * Presentation controls of an embedded editor: set by its provider, or requested by the guest through the
 * web editor protocol (`setPresentationPreferences`). Provider values take precedence.
 */
export type IframeEditorPresentationOptions = PresentationPreferences;

export type IframeEditorPresentationMode = PresentationMode;

export interface ResolvedIframeEmbeddedEditor {
	readonly html: string;
	readonly runtimeKey: string;
	readonly resourceBaseUrl?: string;
	readonly hostTransport?: boolean;
	readonly contentType?: ContentType;
	readonly initialHeight?: number;
	readonly sandbox?: IframeSandboxOptions;
	readonly presentation?: IframeEditorPresentationOptions;
}

export interface VirtualizedIframeEmbeddedEditorOptions {
	readonly providers: readonly IframeEmbeddedEditorProvider[];
	readonly root?: Element | Document | null;
	readonly frameRoot?: HTMLElement;
	readonly scriptNonce?: string;
	readonly themeCss?: string | (() => string);
	/** Notify existing frames when the CSS returned by themeCss changes. */
	readonly onDidChangeTheme?: (listener: () => void) => IDisposable;
	/** Optional same-origin document URL to load before writing the iframe content. */
	readonly iframeBootstrapUrl?: string;
	readonly defaultHeight?: number;
	readonly onAmbiguous?: (language: string, providers: readonly CodeBlockEditorProviderDefinition[]) => void;
	readonly onDidChange?: () => void;
}

export interface VirtualizedIframeEmbeddedEditorDiagnostics {
	readonly logicalEditors: number;
	readonly leasedFrames: number;
	readonly idleFrames: number;
	readonly descriptorCacheEntries: number;
	readonly descriptorCacheHits: number;
}

const BASE_CSS = `
	:root { color-scheme: light dark; }
	html, body { margin: 0; padding: 0; background: transparent; }
	body {
		font-family: var(--vscode-font-family, system-ui, sans-serif);
		font-size: var(--vscode-font-size, 13px);
		color: var(--vscode-foreground, #1e1e1e);
		box-sizing: border-box;
	}
`;

/**
 * Private channel between the host and the bootstrap script it injects into every guest. It carries theme CSS
 * to the guest, and the document height (a sizing fallback for guests without the web editor protocol) and
 * Escape (to leave full view) back. Guests use the web editor protocol instead.
 */
const CONTROL_MESSAGE = 'vscode-markdown-editor::control';
const MAX_IFRAME_HEIGHT = 10_000;
const TOOLBAR_HEIGHT = 28;
/** Distance between the iframe and its hover outline. */
const OUTLINE_OFFSET = 10;
/** Gap between the hover outline and the toolbar above it. */
const TOOLBAR_GAP = 4;
/** Inset of the toolbar when it overlays the iframe (full view, or no room above the block). */
const TOOLBAR_INSET = 6;
/** Grips span from the iframe edge to just past the outline drawn on it. */
const GRIP_SIZE = OUTLINE_OFFSET + 4;
/** Grip drags within this distance of a size preset snap to it. */
const SNAP_DISTANCE = 16;
const GRIP_KEYBOARD_STEP = 20;

export function buildIframeEmbeddedEditorSrcdoc(authorHtml: string, resourceBaseUrl: string | undefined, themeCss: string | undefined, scriptNonce: string | undefined): string {
	const safeBaseCss = BASE_CSS.replace(/<\/style/gi, '<\\/style');
	const safeThemeCss = (themeCss ?? '').replace(/<\/style/gi, '<\\/style');
	const nonceAttribute = scriptNonce ? ` nonce="${escapeHtmlAttribute(scriptNonce)}"` : '';
	const baseElement = resourceBaseUrl ? `<base href="${escapeHtmlAttribute(resourceBaseUrl)}">` : '';
	const injection = baseElement +
		`<style data-vscode-markdown-editor-base>${safeBaseCss}</style>` +
		`<style data-vscode-markdown-editor-theme>${safeThemeCss}</style>` +
		`<script${nonceAttribute}>(function(){` +
		`var t=document.currentScript.previousElementSibling;` +
		`var sendSize=function(){parent.postMessage({type:${JSON.stringify(CONTROL_MESSAGE)},height:Math.max(document.documentElement.scrollHeight,document.body?document.body.scrollHeight:0)},"*");};` +
		`addEventListener("message",function(e){if(e.source!==parent)return;var d=e.data;if(d&&d.type===${JSON.stringify(CONTROL_MESSAGE)}&&typeof d.themeCss==="string")t.textContent=d.themeCss;});` +
		`addEventListener("load",sendSize);new ResizeObserver(sendSize).observe(document.documentElement);` +
		`addEventListener("keydown",function(e){if(e.key==="Escape"&&!e.defaultPrevented)parent.postMessage({type:${JSON.stringify(CONTROL_MESSAGE)},action:"exit-full-view"},"*");});` +
		`})();<\/script>`;

	const html = scriptNonce
		? authorHtml.replace(/<script\b(?![^>]*\bnonce\s*=)/gi, `<script${nonceAttribute}`)
		: authorHtml;
	const headMatch = html.match(/<head[^>]*>/i);
	if (headMatch?.index !== undefined) {
		const end = headMatch.index + headMatch[0].length;
		return html.slice(0, end) + injection + html.slice(end);
	}
	const htmlMatch = html.match(/<html[^>]*>/i);
	if (htmlMatch?.index !== undefined) {
		const end = htmlMatch.index + htmlMatch[0].length;
		return html.slice(0, end) + `<head>${injection}</head>` + html.slice(end);
	}
	return `<!doctype html><html><head>${injection}</head><body>${html}</body></html>`;
}

function escapeHtmlAttribute(value: string): string {
	return value.replaceAll('&', '&amp;').replaceAll('"', '&quot;');
}

export class VirtualizedIframeEmbeddedEditorFactory implements IEmbeddedCodeEditorFactory, IDisposable {
	private readonly _frameLayer: HTMLElement;
	private _frameRoot: HTMLElement | undefined;
	private _restoreFrameRootPosition: string | undefined;
	private _layoutObserver: ResizeObserver | undefined;
	private _layoutFrame = 0;
	private readonly _observer: IntersectionObserver | undefined;
	private readonly _themeSubscription: IDisposable | undefined;
	private readonly _logicalEditors = new Set<VirtualizedIframeEmbeddedEditor>();
	private readonly _pools = new Map<string, PhysicalIframePool>();
	private readonly _descriptorCache = new Map<string, Promise<ResolvedIframeEmbeddedEditor | undefined>>();
	private readonly _rejectedProviders = new Set<string>();
	private _providers: readonly IframeEmbeddedEditorProvider[];
	private _generation = 0;
	private _descriptorCacheHits = 0;
	private _disposed = false;

	constructor(private readonly _options: VirtualizedIframeEmbeddedEditorOptions) {
		this._providers = _options.providers;
		this._frameLayer = document.createElement('div');
		this._frameLayer.style.position = 'absolute';
		this._frameLayer.style.inset = '0';
		this._frameLayer.style.height = '0';
		this._frameLayer.style.pointerEvents = 'none';
		this._frameLayer.style.zIndex = '1';
		if (_options.frameRoot) {
			this._setFrameRoot(_options.frameRoot);
		}
		this._observer = typeof IntersectionObserver === 'undefined'
			? undefined
			: new IntersectionObserver(entries => {
				for (const entry of entries) {
					const editor = Array.from(this._logicalEditors).find(candidate => candidate.element === entry.target);
					editor?.setVisible(entry.isIntersecting);
				}
			}, { root: _options.root ?? null });
		this._themeSubscription = _options.onDidChangeTheme?.(() => {
			for (const pool of this._pools.values()) {
				pool.updateTheme();
			}
		});
	}

	public updateProviders(providers: readonly IframeEmbeddedEditorProvider[]): void {
		this._providers = providers;
		this._generation++;
		this._descriptorCache.clear();
		this._rejectedProviders.clear();
		this._descriptorCacheHits = 0;
		this._disposePools();
		for (const editor of this._logicalEditors) {
			editor.invalidate();
		}
		this._options.onDidChange?.();
	}

	public get diagnostics(): VirtualizedIframeEmbeddedEditorDiagnostics {
		let leasedFrames = 0;
		let idleFrames = 0;
		for (const pool of this._pools.values()) {
			leasedFrames += pool.leasedFrames;
			idleFrames += pool.idleFrames;
		}
		return {
			logicalEditors: this._logicalEditors.size,
			leasedFrames,
			idleFrames,
			descriptorCacheEntries: this._descriptorCache.size,
			descriptorCacheHits: this._descriptorCacheHits,
		};
	}

	public create(language: string, infoString: string, initialContent: string): IEmbeddedCodeEditor | undefined {
		const selection = selectCodeBlockEditorProvider(this._providers, language);
		if (!selection) {
			return undefined;
		}
		if (selection.kind === 'ambiguous') {
			this._options.onAmbiguous?.(language, selection.providers);
			return undefined;
		}
		const requestKey = descriptorRequestKey(selection.provider.id, infoString);
		if (this._rejectedProviders.has(requestKey)) {
			return undefined;
		}
		const editor = new VirtualizedIframeEmbeddedEditor(
			this,
			selection.provider,
			infoString,
			initialContent,
			this._options.defaultHeight ?? 120,
			this._generation,
		);
		this._logicalEditors.add(editor);
		this._observer?.observe(editor.element);
		if (this._layoutObserver) {
			editor.observeLayout(this._layoutObserver);
		}
		if (!this._observer) {
			editor.setVisible(true);
		}
		return editor;
	}

	public dispose(): void {
		if (this._disposed) { return; }
		this._disposed = true;
		this._observer?.disconnect();
		this._themeSubscription?.dispose();
		this._layoutObserver?.disconnect();
		cancelAnimationFrame(this._layoutFrame);
		window.removeEventListener('resize', this._scheduleLayout);
		window.removeEventListener('scroll', this._scheduleLayout, true);
		for (const editor of Array.from(this._logicalEditors)) {
			editor.dispose();
		}
		this._disposePools();
		this._frameLayer.remove();
		if (this._frameRoot && this._restoreFrameRootPosition !== undefined) {
			this._frameRoot.style.position = this._restoreFrameRootPosition;
		}
	}

	public remove(editor: VirtualizedIframeEmbeddedEditor): void {
		this._observer?.unobserve(editor.element);
		this._layoutObserver?.unobserve(editor.element);
		this._logicalEditors.delete(editor);
		editor.frame?.unbind();
	}

	public enterFullView(editor: VirtualizedIframeEmbeddedEditor): void {
		for (const other of this._logicalEditors) {
			if (other !== editor) { other.exitFullView(); }
		}
		this._frameLayer.style.zIndex = '11';
	}

	public exitFullView(): void {
		this._frameLayer.style.zIndex = '1';
	}

	public async resolve(editor: VirtualizedIframeEmbeddedEditor, generation: number): Promise<void> {
		const requestKey = descriptorRequestKey(editor.provider.id, editor.infoString);
		let descriptorPromise = this._descriptorCache.get(requestKey);
		let descriptor: ResolvedIframeEmbeddedEditor | undefined;
		try {
			if (!descriptorPromise) {
				descriptorPromise = editor.provider.resolve(editor.infoString);
				this._descriptorCache.set(requestKey, descriptorPromise);
			} else {
				this._descriptorCacheHits++;
			}
			descriptor = await descriptorPromise;
		} catch {
			if (descriptorPromise && this._descriptorCache.get(requestKey) === descriptorPromise) {
				this._descriptorCache.delete(requestKey);
			}
			this._rejectEditor(editor, generation, requestKey);
			return;
		}
		if (
			this._disposed
			|| editor.disposed
			|| generation !== this._generation
			|| !descriptor
		) {
			this._rejectEditor(editor, generation, requestKey);
			return;
		}
		const poolKey = getIframeEmbeddedEditorPoolKey(editor.provider.id, descriptor);
		let pool = this._pools.get(poolKey);
		if (!pool) {
			const frameRoot = this._ensureFrameRoot(editor);
			pool = new PhysicalIframePool(
				editor.provider,
				descriptor,
				this._frameLayer,
				frameRoot,
				this._options.scriptNonce,
				this._options.themeCss,
				this._options.iframeBootstrapUrl,
			);
			this._pools.set(poolKey, pool);
		}
		editor.resolve(pool);
	}

	private _rejectEditor(editor: VirtualizedIframeEmbeddedEditor, generation: number, requestKey: string): void {
		editor.resolve(undefined);
		if (!this._disposed && !editor.disposed && generation === this._generation) {
			this._rejectedProviders.add(requestKey);
			this._options.onDidChange?.();
		}
	}

	private _ensureFrameRoot(editor: VirtualizedIframeEmbeddedEditor): HTMLElement {
		return this._frameRoot ?? this._setFrameRoot(
			editor.element.closest<HTMLElement>('.md-editor')
				?? (this._options.root instanceof HTMLElement ? this._options.root : document.body),
		);
	}

	private _setFrameRoot(frameRoot: HTMLElement): HTMLElement {
		this._frameRoot = frameRoot;
		if (frameRoot !== document.body && getComputedStyle(frameRoot).position === 'static') {
			this._restoreFrameRootPosition = frameRoot.style.position;
			frameRoot.style.position = 'relative';
		}
		frameRoot.appendChild(this._frameLayer);
		if (typeof ResizeObserver !== 'undefined') {
			this._layoutObserver = new ResizeObserver(() => this._scheduleLayout());
			this._layoutObserver.observe(frameRoot);
			for (let parent = frameRoot.parentElement; parent; parent = parent.parentElement) {
				this._layoutObserver.observe(parent);
			}
			for (const editor of this._logicalEditors) {
				editor.observeLayout(this._layoutObserver);
			}
		}
		window.addEventListener('resize', this._scheduleLayout);
		window.addEventListener('scroll', this._scheduleLayout, true);
		return frameRoot;
	}

	private readonly _scheduleLayout = (): void => {
		if (this._layoutFrame) { return; }
		this._layoutFrame = requestAnimationFrame(() => {
			this._layoutFrame = 0;
			this.layout();
		});
	};

	public layout(): void {
		for (const pool of this._pools.values()) {
			pool.layout();
		}
	}

	private _disposePools(): void {
		for (const pool of this._pools.values()) {
			pool.dispose();
		}
		this._pools.clear();
	}
}

class VirtualizedIframeEmbeddedEditor implements IEmbeddedCodeEditor {
	public readonly element: HTMLElement;
	public onEdit?: (edit: StringEdit) => void;
	public readonly estimateHeight: () => number;
	public frame: PhysicalIframe | undefined;
	public disposed = false;
	public visible = false;
	public readonly infoString: string;

	private readonly _frameHost: HTMLElement;
	private _content: string;
	private _readOnly = false;
	private _pool: PhysicalIframePool | undefined;
	private _resolved = false;
	private _height: number;
	private _guestPresentation: IframeEditorPresentationOptions = {};
	private _userHeight: number | undefined;
	private _contentHeight: number | undefined;
	/** 0 keeps the text column width, 1 spans the Markdown viewport; values in between interpolate both edges. */
	private _widthFraction = 0;
	private _fullView = false;
	public resizing = false;
	private _actions: HTMLElement | undefined;

	public get presentation(): IframeEditorPresentationOptions {
		return { ...this._guestPresentation, ...this._pool?.descriptor.presentation };
	}

	public get mode(): IframeEditorPresentationMode {
		return this._fullView ? 'full-view' : this._widthFraction === 1 ? 'full-width' : 'inline';
	}

	public get widthFraction(): number {
		return this._widthFraction;
	}

	/** The toolbar holds the copy action and full view; resizing uses grips on the outline. */
	public get toolbarHeight(): number {
		return this._actions || this.presentation.fullView ? TOOLBAR_HEIGHT : 0;
	}

	public get pinned(): boolean { return this._fullView || this.resizing || this.hasFocus(); }

	constructor(
		private readonly _factory: VirtualizedIframeEmbeddedEditorFactory,
		public readonly provider: IframeEmbeddedEditorProvider,
		infoString: string,
		initialContent: string,
		initialHeight: number,
		generation: number,
	) {
		this.infoString = infoString;
		this._content = initialContent;
		this._height = initialHeight;
		this.element = document.createElement('div');
		this.element.style.width = '100%';
		this.element.style.minHeight = `${initialHeight}px`;
		this._frameHost = document.createElement('div');
		this._frameHost.style.width = '100%';
		this.element.appendChild(this._frameHost);
		this.estimateHeight = () => parseFloat(this.element.style.minHeight) || initialHeight;
		void this._factory.resolve(this, generation);
	}

	public setContent(content: string): void {
		if (content === this._content) { return; }
		this._content = content;
		this.frame?.bind(this);
	}

	public setReadOnly(readOnly: boolean): void {
		if (this._readOnly === readOnly) { return; }
		this._readOnly = readOnly;
		this.frame?.bind(this);
	}

	public setActions(actions: HTMLElement): void {
		if (this._actions === actions) { return; }
		this._actions = actions;
		this.mountActions();
		this.frame?.layout(this);
	}

	public mountActions(toolbar?: HTMLElement): void {
		if (!this._actions) { return; }
		const target = toolbar ?? this.element;
		if (this._actions.parentElement !== target) {
			target.prepend(this._actions);
		}
	}

	public setVisible(visible: boolean): void {
		this.visible = visible;
		if (!this._resolved) { return; }
		if (visible) {
			this._pool?.acquire(this);
		} else if (!this.pinned) {
			this._pool?.release(this);
		}
	}

	public resolve(pool: PhysicalIframePool | undefined): void {
		if (this.disposed) { return; }
		this._resolved = true;
		this._pool = pool;
		if (!pool) {
			this._renderFallback();
		} else if (pool.descriptor.initialHeight !== undefined) {
			this.applyHeight(pool.descriptor.initialHeight);
		}
		if (this.visible) {
			pool?.acquire(this);
		}
	}

	public invalidate(): void {
		this.frame?.unbind();
		this._pool = undefined;
		this._resolved = false;
		this._renderFallback();
	}

	public bindFrame(frame: PhysicalIframe): void {
		this.frame = frame;
		frame.layout(this);
	}

	public unbindFrame(height: number): void {
		if (this.frame) {
			this.element.style.minHeight = `${height}px`;
			this.frame = undefined;
		}
	}

	public applyGuestText(text: string): void {
		if (text === this._content) { return; }
		const edit = StringEdit.replace(OffsetRange.ofLength(this._content.length), text);
		this._content = text;
		this.onEdit?.(edit);
	}

	public applyHeight(height: number): void {
		const value = this._userHeight ?? this._clampAutomaticHeight(height);
		this._height = value;
		this.element.style.minHeight = `${value}px`;
		this._frameHost.style.height = `${value}px`;
		if (this.frame) {
			this.frame.layout(this);
		}
	}

	public get inlineHeight(): number {
		return this._height;
	}

	/** The content-driven height that a reset restores and grip drags snap to. */
	public get automaticHeight(): number {
		return this._clampAutomaticHeight(this._contentHeight ?? this._pool?.descriptor.initialHeight ?? 120);
	}

	/** The guest's preferred content height from its latest size report; kept across frame reuse. */
	public get contentHeight(): number | undefined {
		return this._contentHeight;
	}

	/**
	 * Records the guest's preferred content height. Protocol reports describe the content regardless of the
	 * frame's height, so they stay the snap and reset target while the user has chosen a height. Document
	 * measurements, the fallback for guests without the protocol, follow the frame and are only used while
	 * the frame follows the content.
	 */
	public setContentHeight(height: number, source: 'protocol' | 'document'): void {
		if (source === 'document' && (this._userHeight !== undefined || this._fullView)) { return; }
		this._contentHeight = clampIframeHeight(height);
		if (this._userHeight === undefined) {
			this.applyHeight(this._contentHeight);
		}
	}

	public resize(height: number): void {
		const value = clampIframeHeight(Math.max(this.presentation.minHeight ?? 1, height));
		if (Math.abs(value - this.automaticHeight) <= SNAP_DISTANCE) {
			this.resetHeight();
			return;
		}
		this._userHeight = value;
		this.applyHeight(value);
	}

	public resetHeight(): void {
		this._userHeight = undefined;
		this.applyHeight(this.automaticHeight);
	}

	private _clampAutomaticHeight(height: number): number {
		const { minHeight, maxAutomaticHeight } = this.presentation;
		return Math.max(minHeight ?? 1, Math.min(maxAutomaticHeight ?? MAX_IFRAME_HEIGHT, clampIframeHeight(height)));
	}

	public setGuestPresentation(options: IframeEditorPresentationOptions): void {
		const height = this.inlineHeight;
		this._guestPresentation = options;
		if (!this.presentation.fullWidth) { this._widthFraction = 0; }
		if (!this.presentation.fullView) { this.exitFullView(); }
		this.applyHeight(height);
		this.frame?.notifyPresentation();
	}

	/** Widens the editor between the text column (0) and the Markdown viewport (1), snapping to both ends. */
	public setWidthFraction(fraction: number, snapRange: number): void {
		if (!this.presentation.fullWidth) { return; }
		const value = Math.max(0, Math.min(1, fraction));
		const snapped = value * snapRange <= SNAP_DISTANCE ? 0 : (1 - value) * snapRange <= SNAP_DISTANCE ? 1 : value;
		if (snapped === this._widthFraction) { return; }
		const mode = this.mode;
		this._widthFraction = snapped;
		this.frame?.layout(this);
		if (this.mode !== mode) { this.frame?.notifyPresentation(); }
	}

	public toggleFullView(): void {
		if (this._fullView) { this.exitFullView(); return; }
		if (!this.presentation.fullView) { return; }
		this._factory.enterFullView(this);
		this.frame?.rememberScroll();
		this._fullView = true;
		this.frame?.layout(this);
		this.frame?.notifyPresentation();
	}

	public exitFullView(): void {
		if (!this._fullView) { return; }
		this._fullView = false;
		this._factory.exitFullView();
		this.frame?.restoreScroll();
		this.frame?.layout(this);
		this.frame?.notifyPresentation();
		this.frame?.focusFullViewButton();
	}

	public observeLayout(observer: ResizeObserver): void {
		observer.observe(this.element);
	}

	public hasFocus(): boolean {
		return this.frame?.hasFocus() ?? false;
	}

	public get content(): string { return this._content; }
	public get readOnly(): boolean { return this._readOnly; }
	public get frameHost(): HTMLElement { return this._frameHost; }

	public dispose(): void {
		if (this.disposed) { return; }
		this.exitFullView();
		this.disposed = true;
		this._factory.remove(this);
		this.element.remove();
	}

	private _renderFallback(): void {
		this._frameHost.style.height = '';
		const pre = document.createElement('pre');
		const code = document.createElement('code');
		code.textContent = this._content;
		pre.appendChild(code);
		this._frameHost.replaceChildren(pre);
	}
}

class PhysicalIframePool implements IDisposable {
	public readonly descriptor: ResolvedIframeEmbeddedEditor;
	private readonly _frames = new Set<PhysicalIframe>();

	constructor(
		private readonly _provider: IframeEmbeddedEditorProvider,
		descriptor: ResolvedIframeEmbeddedEditor,
		private readonly _frameLayer: HTMLElement,
		private readonly _frameRoot: HTMLElement,
		private readonly _scriptNonce: string | undefined,
		private readonly _themeCss: string | (() => string) | undefined,
		private readonly _iframeBootstrapUrl: string | undefined,
	) {
		this.descriptor = descriptor;
	}

	public get leasedFrames(): number {
		return Array.from(this._frames).filter(frame => frame.editor !== undefined).length;
	}

	public get idleFrames(): number {
		return this._frames.size - this.leasedFrames;
	}

	public acquire(editor: VirtualizedIframeEmbeddedEditor): void {
		if (editor.frame) {
			editor.frame.bind(editor);
			return;
		}
		const idle = Array.from(this._frames).find(frame => frame.editor === undefined);
		const frame = idle ?? this._createFrame();
		frame.bind(editor);
	}

	public release(editor: VirtualizedIframeEmbeddedEditor): void {
		const frame = editor.frame;
		if (!frame || frame.editor !== editor || editor.pinned) { return; }
		frame.unbind();
	}

	public park(iframe: HTMLIFrameElement): void {
		iframe.style.top = '-100000px';
		iframe.style.left = 'auto';
		iframe.style.right = '100%';
	}

	public dispose(): void {
		for (const frame of this._frames) {
			frame.dispose();
		}
		this._frames.clear();
	}

	public layout(): void {
		for (const frame of this._frames) {
			if (frame.editor) {
				frame.layout(frame.editor);
			}
		}
	}

	public updateTheme(): void {
		for (const frame of this._frames) {
			frame.updateTheme();
		}
	}

	private _createFrame(): PhysicalIframe {
		const hostTransport = this.descriptor.hostTransport
			? this._provider.createHostTransport?.(this.descriptor.runtimeKey)
			: undefined;
		const frame = new PhysicalIframe(
			this,
			this.descriptor,
			hostTransport,
			this._frameLayer,
			this._frameRoot,
			this._scriptNonce,
			this._themeCss,
			this._iframeBootstrapUrl,
		);
		this._frames.add(frame);
		return frame;
	}
}

class PhysicalIframe implements IDisposable {
	public readonly iframe: HTMLIFrameElement;
	public editor: VirtualizedIframeEmbeddedEditor | undefined;
	public readonly pool: PhysicalIframePool;

	private _host: WebEditorHost | undefined;
	private _transport: WindowMessageTransport | undefined;
	private _pendingEditor: VirtualizedIframeEmbeddedEditor | undefined;
	private _guestReportsSize = false;
	private _disposed = false;
	private readonly _onWindowMessage: (event: MessageEvent) => void;
	private readonly _surface: HTMLDivElement;
	private readonly _toolbar: HTMLDivElement;
	private readonly _fullViewButton: HTMLButtonElement;
	private readonly _heightGrip: HTMLDivElement;
	private readonly _widthGrip: HTMLDivElement;
	private _drag: GripDrag | undefined;
	/** Client-pixel distance the right edge travels between column width and full width. */
	private _widthTravel = 0;
	private _guestPresentation: IframeEditorPresentationOptions = {};
	private _scrollPositions: { readonly element: HTMLElement; readonly top: number; readonly left: number }[] = [];

	constructor(
		pool: PhysicalIframePool,
		private readonly _descriptor: ResolvedIframeEmbeddedEditor,
		private readonly _hostTransport: IframeEmbeddedEditorHostTransport | undefined,
		frameLayer: HTMLElement,
		private readonly _frameRoot: HTMLElement,
		private readonly _scriptNonce: string | undefined,
		private readonly _themeCss: string | (() => string) | undefined,
		private readonly _iframeBootstrapUrl: string | undefined,
	) {
		this.pool = pool;
		this._surface = document.createElement('div');
		this._surface.className = 'md-iframe-surface';
		const iframe = document.createElement('iframe');
		iframe.setAttribute('sandbox', sandboxValue(_descriptor.sandbox));
		iframe.setAttribute('allow', _descriptor.sandbox?.clipboardWrite ? 'clipboard-write' : '');
		iframe.style.width = '100%';
		iframe.style.border = 'none';
		iframe.style.display = 'block';
		iframe.style.position = 'absolute';
		iframe.style.pointerEvents = 'auto';
		iframe.style.background = 'var(--md-iframe-background, #fff)';
		iframe.style.height = `${_descriptor.initialHeight ?? 120}px`;
		pool.park(iframe);
		iframe.addEventListener('blur', () => {
			const editor = this.editor;
			if (editor && !editor.visible) {
				this.pool.release(editor);
			}
		});
		this.iframe = iframe;
		iframe.className = 'md-iframe-frame';
		this._toolbar = document.createElement('div');
		this._toolbar.className = 'md-iframe-toolbar';
		this._toolbar.setAttribute('data-md-editor-chrome', '');
		this._toolbar.setAttribute('role', 'toolbar');
		this._toolbar.setAttribute('aria-label', 'Embedded editor presentation');
		this._fullViewButton = this._addButton('Full view', 'screen-full', () => this.editor?.toggleFullView());
		this._toolbar.addEventListener('keydown', event => {
			if (event.key === 'Escape' && this.editor?.mode === 'full-view') {
				event.preventDefault();
				event.stopPropagation();
				this.editor.exitFullView();
			}
		}, true);
		this._heightGrip = this._createGrip('height', 'Resize embedded editor height');
		this._widthGrip = this._createGrip('width', 'Resize embedded editor width');
		this._onWindowMessage = event => {
			if (event.source !== iframe.contentWindow) { return; }
			const data = event.data as { type?: unknown; height?: unknown; action?: unknown } | undefined;
			if (data?.type !== CONTROL_MESSAGE) { return; }
			if (data.action === 'exit-full-view') {
				this.editor?.exitFullView();
				return;
			}
			if (typeof data.height !== 'number' || !Number.isFinite(data.height)) { return; }
			// The bootstrap measures the document. A guest that reports its size through the protocol knows its
			// content height better.
			if (this._guestReportsSize) { return; }
			this.editor?.setContentHeight(data.height, 'document');
		};
		window.addEventListener('message', this._onWindowMessage);
		this._surface.append(iframe, this._toolbar, this._heightGrip, this._widthGrip);
		frameLayer.appendChild(this._surface);
		this._surface.hidden = true;
		this._toolbar.hidden = true;
		this._heightGrip.hidden = true;
		this._widthGrip.hidden = true;
		queueMicrotask(() => this._setup());
	}

	public bind(editor: VirtualizedIframeEmbeddedEditor): void {
		if (this.editor === editor) {
			this._host?.setText(editor.content);
			this._host?.setReadOnly(editor.readOnly);
			editor.applyHeight(getIframeEmbeddedEditorBindingHeight(editor.contentHeight, editor.inlineHeight));
			return;
		}
		if (this.editor && this.editor !== editor) {
			this.unbind();
		}
		this._pendingEditor = editor;
		if (this._host) {
			this._host.reuse(editor.content, editor.readOnly);
		}
		this.editor = editor;
		this._pendingEditor = undefined;
		editor.setGuestPresentation(this._guestPresentation);
		editor.bindFrame(this);
		editor.applyHeight(getIframeEmbeddedEditorBindingHeight(editor.contentHeight, editor.inlineHeight));
		this.notifyPresentation();
	}

	public unbind(): void {
		const editor = this.editor;
		if (!editor) { return; }
		editor.exitFullView();
		this._endResize();
		const height = editor.estimateHeight();
		this.editor = undefined;
		editor.mountActions();
		editor.unbindFrame(height);
		this.pool.park(this.iframe);
		this._surface.hidden = true;
		this._toolbar.hidden = true;
		this._heightGrip.hidden = true;
		this._widthGrip.hidden = true;
	}

	public layout(editor: VirtualizedIframeEmbeddedEditor): void {
		if (this.editor !== editor) { return; }
		const columnRect = editor.frameHost.getBoundingClientRect();
		const rootRect = getElementClientRect(this._frameRoot);
		const isBody = this._frameRoot === document.body;
		const fullView = editor.mode === 'full-view';
		const presentationViewport = getIframePresentationViewport(this._frameRoot);
		// Full width keeps room for the hover outline beside the frame; full view covers the whole viewport.
		const outlineClientOffset = OUTLINE_OFFSET / Math.max(Number.EPSILON, clientDeltaToScrollDelta(this._frameRoot, 1, 0).x);
		const fullWidthViewport = insetHorizontal(presentationViewport, columnRect, outlineClientOffset);
		const viewport = fullView ? presentationViewport : interpolateHorizontal(columnRect, fullWidthViewport, editor.widthFraction);
		this._widthTravel = Math.max(0, fullWidthViewport.left + fullWidthViewport.width - columnRect.right);
		const position = clientDeltaToScrollDelta(this._frameRoot,
			viewport.left - (isBody ? 0 : rootRect.left),
			(fullView ? viewport.top : columnRect.top) - (isBody ? 0 : rootRect.top));
		const size = clientDeltaToScrollDelta(this._frameRoot, viewport.width, viewport.height);
		const top = position.y + (isBody ? window.scrollY : this._frameRoot.scrollTop);
		const left = position.x + (isBody ? window.scrollX : this._frameRoot.scrollLeft);
		const width = size.x;
		const height = fullView ? Math.max(1, size.y) : editor.inlineHeight;
		this._surface.hidden = false;
		this._surface.style.top = `${top}px`;
		this._surface.style.left = `${left}px`;
		this._surface.style.width = `${width}px`;
		this._surface.style.height = `${height}px`;
		this._surface.style.zIndex = fullView ? '10' : '';
		this._surface.classList.toggle('md-iframe-surface-full-view', fullView);
		const room = this._horizontalRoom(viewport, fullView);
		const outline = { left: Math.min(OUTLINE_OFFSET, room.left), right: Math.min(OUTLINE_OFFSET, room.right) };
		this._surface.style.setProperty('--md-iframe-outline-inset', `${-OUTLINE_OFFSET}px ${-outline.right}px ${-OUTLINE_OFFSET}px ${-outline.left}px`);
		const zIndex = fullView ? '10' : '';
		this.iframe.style.zIndex = zIndex;
		this._toolbar.style.zIndex = fullView ? '11' : '1';
		this.iframe.style.top = '0';
		this.iframe.style.left = '0';
		this.iframe.style.right = '';
		this.iframe.style.width = `${width}px`;
		this.iframe.style.height = `${height}px`;
		this._toolbar.hidden = editor.toolbarHeight === 0;
		this._toolbar.classList.toggle('md-iframe-toolbar-full-view', fullView);
		editor.mountActions(this._toolbar.hidden ? undefined : this._toolbar);
		// Prefer the space above the outline; overlay the iframe when that would leave the scroll content.
		const toolbarTopOutside = -(OUTLINE_OFFSET + TOOLBAR_GAP + editor.toolbarHeight);
		const outside = !fullView && top + toolbarTopOutside >= 0;
		this._toolbar.classList.toggle('md-iframe-toolbar-outside', outside);
		this._toolbar.style.setProperty('--md-iframe-toolbar-bridge', `${OUTLINE_OFFSET + TOOLBAR_GAP}px`);
		this._toolbar.style.top = `${outside ? toolbarTopOutside : TOOLBAR_INSET}px`;
		this._toolbar.style.left = `${outside ? width + outline.right : width - TOOLBAR_INSET}px`;
		this._toolbar.style.maxWidth = `${Math.max(0, width - 2 * TOOLBAR_INSET)}px`;
		this._toolbar.style.height = `${editor.toolbarHeight}px`;
		this._fullViewButton.hidden = !editor.presentation.fullView;
		this._setButtonAppearance(this._fullViewButton, fullView ? 'Exit full view' : 'Full view', fullView ? 'screen-normal' : 'screen-full');
		this._fullViewButton.setAttribute('aria-pressed', String(fullView));

		// Grips span from the iframe edge across the outline; their bar is drawn on the outline.
		const heightGrip = this._heightGrip;
		heightGrip.hidden = !editor.presentation.resizable || fullView;
		heightGrip.style.top = `${height}px`;
		heightGrip.style.left = '0';
		heightGrip.style.width = `${width}px`;
		heightGrip.style.height = `${GRIP_SIZE}px`;
		heightGrip.style.setProperty('--md-iframe-grip-line', `${OUTLINE_OFFSET}px`);
		heightGrip.setAttribute('aria-valuenow', String(Math.round(height)));
		heightGrip.setAttribute('aria-valuemin', String(editor.presentation.minHeight ?? 1));
		heightGrip.setAttribute('aria-valuemax', String(MAX_IFRAME_HEIGHT));

		const widthGrip = this._widthGrip;
		widthGrip.hidden = !editor.presentation.fullWidth || fullView || this._widthTravel <= SNAP_DISTANCE;
		const lineX = width + outline.right;
		const beyondLine = Math.min(GRIP_SIZE - OUTLINE_OFFSET, room.right - outline.right);
		widthGrip.style.top = '0';
		widthGrip.style.left = `${lineX - OUTLINE_OFFSET}px`;
		widthGrip.style.width = `${OUTLINE_OFFSET + beyondLine}px`;
		widthGrip.style.height = `${height}px`;
		widthGrip.style.setProperty('--md-iframe-grip-line', `${OUTLINE_OFFSET}px`);
		const columnWidth = clientDeltaToScrollDelta(this._frameRoot, columnRect.width, 0).x;
		const fullWidth = clientDeltaToScrollDelta(this._frameRoot, fullWidthViewport.width, 0).x;
		widthGrip.setAttribute('aria-valuenow', String(Math.round(width)));
		widthGrip.setAttribute('aria-valuemin', String(Math.round(columnWidth)));
		widthGrip.setAttribute('aria-valuemax', String(Math.round(fullWidth)));
	}

	/** Horizontal space beside the frame within the frame root's visible area, in scroll pixels. */
	private _horizontalRoom(frame: { readonly left: number; readonly width: number }, fullView: boolean): { readonly left: number; readonly right: number } {
		if (fullView) { return { left: 0, right: 0 }; }
		const root = getIframePresentationViewport(this._frameRoot);
		const space = (clientDelta: number) => Math.max(0, clientDeltaToScrollDelta(this._frameRoot, clientDelta, 0).x);
		return {
			left: space(frame.left - root.left),
			right: space(root.left + root.width - (frame.left + frame.width)),
		};
	}

	public rememberScroll(): void {
		this._scrollPositions = [];
		for (let element: HTMLElement | null = this._frameRoot; element; element = element.parentElement) {
			this._scrollPositions.push({ element, top: element.scrollTop, left: element.scrollLeft });
		}
	}

	public restoreScroll(): void {
		for (const { element, top, left } of this._scrollPositions) {
			element.scrollTop = top;
			element.scrollLeft = left;
		}
		this._scrollPositions = [];
	}

	public notifyPresentation(): void {
		if (this.editor) {
			this._host?.setPresentationMode(this.editor.mode);
		}
	}

	public focusFullViewButton(): void {
		this._fullViewButton.focus({ preventScroll: true });
	}

	public hasFocus(): boolean {
		const root = this.iframe.getRootNode();
		const active = root instanceof ShadowRoot ? root.activeElement : document.activeElement;
		return active === this.iframe || this._toolbar.contains(active) || active === this._heightGrip || active === this._widthGrip;
	}

	private _addButton(label: string, icon: string, run: () => void): HTMLButtonElement {
		const button = document.createElement('button');
		button.type = 'button';
		const glyph = document.createElement('span');
		glyph.setAttribute('aria-hidden', 'true');
		button.appendChild(glyph);
		this._setButtonAppearance(button, label, icon);
		button.addEventListener('click', event => { event.stopPropagation(); run(); });
		this._toolbar.appendChild(button);
		return button;
	}

	private _setButtonAppearance(button: HTMLButtonElement, label: string, icon: string): void {
		button.title = label;
		button.setAttribute('aria-label', label);
		button.firstElementChild!.className = `codicon codicon-${icon}`;
	}

	/**
	 * Height grips snap to the automatic height; width grips snap to the column and full width.
	 * Double-click resets; arrow keys step (Home/End jump between the width presets).
	 */
	private _createGrip(axis: GripDrag['axis'], label: string): HTMLDivElement {
		const grip = document.createElement('div');
		grip.className = `md-iframe-grip md-iframe-grip-${axis}`;
		grip.setAttribute('data-md-editor-chrome', '');
		grip.tabIndex = 0;
		grip.setAttribute('role', 'separator');
		grip.setAttribute('aria-label', label);
		grip.setAttribute('aria-orientation', axis === 'height' ? 'horizontal' : 'vertical');
		grip.addEventListener('pointerdown', event => {
			const editor = this.editor;
			if (event.button !== 0 || !editor || this._drag) { return; }
			event.preventDefault();
			event.stopPropagation();
			grip.focus({ preventScroll: true, focusVisible: false } as FocusOptions);
			grip.setPointerCapture(event.pointerId);
			this._drag = axis === 'height'
				? { axis, grip, pointerId: event.pointerId, start: event.clientY, height: editor.inlineHeight }
				: { axis, grip, pointerId: event.pointerId, start: event.clientX, fraction: editor.widthFraction, travel: this._widthTravel };
			editor.resizing = true;
			this.iframe.style.pointerEvents = 'none';
		});
		grip.addEventListener('pointermove', event => {
			const drag = this._drag;
			if (drag?.pointerId !== event.pointerId || !this.editor) { return; }
			if (drag.axis === 'height') {
				this.editor.resize(drag.height + clientDeltaToScrollDelta(this._frameRoot, 0, event.clientY - drag.start).y);
			} else if (drag.travel > 0) {
				this.editor.setWidthFraction(drag.fraction + (event.clientX - drag.start) / drag.travel, drag.travel);
			}
		});
		grip.addEventListener('pointerup', () => this._endResize());
		grip.addEventListener('pointercancel', () => this._endResize());
		grip.addEventListener('lostpointercapture', () => this._endResize());
		grip.addEventListener('dblclick', event => {
			event.preventDefault();
			event.stopPropagation();
			if (axis === 'height') {
				this.editor?.resetHeight();
			} else {
				this.editor?.setWidthFraction(0, this._widthTravel);
			}
		});
		grip.addEventListener('keydown', event => {
			const editor = this.editor;
			if (!editor) { return; }
			if (axis === 'height') {
				const delta = event.key === 'ArrowDown' ? GRIP_KEYBOARD_STEP : event.key === 'ArrowUp' ? -GRIP_KEYBOARD_STEP : 0;
				if (!delta) { return; }
				editor.resize(editor.inlineHeight + delta);
			} else {
				const travel = this._widthTravel;
				const step = travel > 0 ? GRIP_KEYBOARD_STEP / travel : 0;
				const target = event.key === 'Home' ? 0 : event.key === 'End' ? 1
					: event.key === 'ArrowRight' ? editor.widthFraction + step
						: event.key === 'ArrowLeft' ? editor.widthFraction - step : undefined;
				if (target === undefined) { return; }
				editor.setWidthFraction(target, travel);
			}
			event.preventDefault();
			event.stopPropagation();
		});
		return grip;
	}

	private _endResize(): void {
		const drag = this._drag;
		this._drag = undefined;
		if (this.editor) { this.editor.resizing = false; }
		this.iframe.style.pointerEvents = 'auto';
		if (drag?.grip.hasPointerCapture(drag.pointerId)) {
			drag.grip.releasePointerCapture(drag.pointerId);
		}
	}

	public dispose(): void {
		if (this._disposed) { return; }
		this._disposed = true;
		this.unbind();
		window.removeEventListener('message', this._onWindowMessage);
		this._host?.dispose();
		this._transport?.dispose();
		this._hostTransport?.dispose();
		this.iframe.remove();
		this._toolbar.remove();
		this._heightGrip.remove();
		this._widthGrip.remove();
		this._surface.remove();
	}

	private _setup(): void {
		if (this._disposed) { return; }
		const contentWindow = this.iframe.contentWindow;
		if (!contentWindow) {
			requestAnimationFrame(() => this._setup());
			return;
		}
		this._transport = new WindowMessageTransport(window, contentWindow);
		const connection = new HubRpcConnection(JsonRpcChannel.create(this._transport));
		const editor = this._pendingEditor ?? this.editor;
		this._host = new WebEditorHost({
			connection,
			contentType: this._descriptor.contentType ?? 'text',
			initialText: editor?.content ?? '',
			readOnly: editor?.readOnly ?? false,
			hostTransport: this._hostTransport,
			supportsPresentation: true,
		});
		this._host.onDidChangeText(({ text }) => this.editor?.applyGuestText(text));
		this._host.onDidReportSize(({ height }) => {
			this._guestReportsSize = true;
			this.editor?.setContentHeight(height, 'protocol');
		});
		this._host.onDidSetPresentationPreferences(preferences => {
			this._guestPresentation = preferences;
			this.editor?.setGuestPresentation(preferences);
		});
		this._host.onDidRequestExitFullView(() => this.editor?.exitFullView());
		if (editor) {
			this._host.setPresentationMode(editor.mode);
		}
		this.iframe.addEventListener('load', () => this.updateTheme(), { once: true });
		const srcdoc = buildIframeEmbeddedEditorSrcdoc(
			this._descriptor.html,
			this._descriptor.resourceBaseUrl,
			this._getThemeCss(),
			this._scriptNonce,
		);
		if (this._iframeBootstrapUrl) {
			this.iframe.addEventListener('load', () => {
				const contentDocument = this.iframe.contentDocument;
				if (!contentDocument) {
					return;
				}
				contentDocument.open();
				contentDocument.write(srcdoc);
				contentDocument.close();
			}, { once: true });
			this.iframe.src = this._iframeBootstrapUrl;
		} else {
			this.iframe.srcdoc = srcdoc;
		}
	}

	private _getThemeCss(): string | undefined {
		return typeof this._themeCss === 'function' ? this._themeCss() : this._themeCss;
	}

	public updateTheme(): void {
		const themeCss = this._getThemeCss();
		if (themeCss !== undefined) {
			this.iframe.contentWindow?.postMessage({ type: CONTROL_MESSAGE, themeCss }, '*');
		}
	}
}

type GripDrag =
	| { readonly axis: 'height'; readonly grip: HTMLElement; readonly pointerId: number; readonly start: number; readonly height: number }
	| { readonly axis: 'width'; readonly grip: HTMLElement; readonly pointerId: number; readonly start: number; readonly fraction: number; readonly travel: number };

type ViewportRect = { readonly left: number; readonly top: number; readonly width: number; readonly height: number };

/** Interpolates both horizontal edges between the column and the full-width rect. */
function interpolateHorizontal(column: DOMRect, full: ViewportRect, fraction: number): ViewportRect {
	const left = column.left + (full.left - column.left) * fraction;
	const right = column.right + (full.left + full.width - column.right) * fraction;
	return { left, top: column.top, width: right - left, height: column.height };
}

/** Shrinks the viewport by `inset` on both sides, but never narrower than the column. */
function insetHorizontal(viewport: ViewportRect, column: DOMRect, inset: number): ViewportRect {
	const left = Math.min(column.left, viewport.left + inset);
	const right = Math.max(column.right, viewport.left + viewport.width - inset);
	return { left, top: viewport.top, width: right - left, height: viewport.height };
}

function sandboxValue(options: IframeSandboxOptions | undefined): string {
	const values = ['allow-scripts', 'allow-same-origin'];
	if (options?.forms) { values.push('allow-forms'); }
	if (options?.downloads) { values.push('allow-downloads'); }
	if (options?.pointerLock) { values.push('allow-pointer-lock'); }
	return values.join(' ');
}

function clampIframeHeight(height: number): number {
	return Math.max(1, Math.min(MAX_IFRAME_HEIGHT, Math.ceil(height)));
}

function getIframePresentationViewport(root: HTMLElement): { left: number; top: number; width: number; height: number } {
	const rect = getElementClientRect(root);
	const clip = getClippingClientRect(root);
	const left = Math.max(rect.left, clip.left);
	const right = Math.min(rect.right, clip.right);
	const top = Math.max(rect.top, clip.top);
	const bottom = Math.min(rect.bottom, clip.bottom);
	return { left, top, width: Math.max(1, right - left), height: Math.max(1, bottom - top) };
}

export function getIframeEmbeddedEditorBindingHeight(reportedHeight: number | undefined, estimatedHeight: number): number {
	return clampIframeHeight(reportedHeight ?? estimatedHeight);
}

function descriptorRequestKey(providerId: string, infoString: string): string {
	return `${providerId}\0${infoString}`;
}

export function getIframeEmbeddedEditorPoolKey(
	providerId: string,
	descriptor: ResolvedIframeEmbeddedEditor,
): string {
	return [
		providerId,
		descriptor.runtimeKey,
		descriptor.html,
		descriptor.resourceBaseUrl ?? '',
		descriptor.hostTransport === true ? 'host-transport' : '',
		descriptor.contentType ?? 'text',
		sandboxValue(descriptor.sandbox),
		descriptor.sandbox?.clipboardWrite === true ? 'clipboard-write' : '',
		JSON.stringify(descriptor.presentation ?? {}),
	].join('\0');
}
